  function fx(kind,p,color){runtime?.effects.push({kind,x:p.x,z:p.z||0,y:p.y||0,t:0,life:kind==='death'?.65:.42,color:color||'#fff'});}function updateEffects(dt){for(let i=runtime.effects.length-1;i>=0;i--){runtime.effects[i].t+=dt;if(runtime.effects[i].t>=runtime.effects[i].life)runtime.effects.splice(i,1);}}function updateDestructibles(dt){runtime.destructibles.forEach(d=>{d.flash=Math.max(0,d.flash-dt);d.tapCd=Math.max(0,d.tapCd-dt);});}
  function checkVictory(){if(!runtime.finished&&runtime.kills>=runtime.killGoal&&playerHoldsFlag())finish(true,`You defeated ${runtime.killGoal} enemies and carried the ${crownLabel()} flag.`);}
  function finish(win,reason){if(!runtime||runtime.finished)return;runtime.finished=true;runtime.phase='finished';runtime.game.classList.remove('moving');document.getElementById('ttdMsEmergencyV4')?.classList.remove('show');const reveal=()=>revealResult(win,reason),p=window.TTDGamePresentation;if(p?.presentOutcome)p.presentOutcome(win?'clear':'fail',{reveal,delay:1850});else setTimeout(reveal,win?1500:2500);}
  function revealResult(win,reason){if(!runtime)return;const box=runtime.result;box.querySelector('h2').textContent=win?'AREA CLAIMED':'RUN FAILED';box.querySelector('p').textContent=reason;box.querySelector('.stats').textContent=`${Math.min(runtime.kills,runtime.killGoal)} / ${runtime.killGoal} enemies defeated · ${runtime.lives} lives left · ${flagLabel()}`;box.classList.add('show');}
  function flagLabel(){const h=flagHolder();if(h)return h.faction==='player'?'Flag secured':'Enemy holds flag';if(!runtime?.flag)return'Flag unavailable';if(runtime.flag.state==='respawning')return'Flag returning';if(runtime.flag.state==='loose')return'Flag loose';return`Flag at ${crownLabel()}`;}

  function update(dt){if(!runtime?.active||runtime.finished)return;updateCamera(dt);runtime.sp=Math.min(999,runtime.sp+dt*.82);for(const e of runtime.entities){if(!e.alive)continue;e.lastHitT=(e.lastHitT||0)+dt;if(e.moving)updateMovement(e,dt);if(e.airborne)updateAirborne(e,dt);e.hitFlash=Math.max(0,e.hitFlash-dt);}updateDeathPlanes();if(runtime.finished)return;updateFlag(dt);updateEnemySpawns(dt);for(const e of enemies())updateAI(e,dt);for(const e of runtime.entities)if(e.alive)updateCombat(e,dt);updateDestructibles(dt);updateEffects(dt);updateEmptyCountdown(dt);runtime.entities=runtime.entities.filter(e=>e.alive||e.hitFlash>0);checkVictory();updateHud();}

  function buildProgress(){const root=document.querySelector('#ttdMsProgressV4 .tiers');if(!root)return;root.innerHTML='';for(const t of runtime.stage.tiers){const d=document.createElement('div');d.className='tier';const pct=(t.y-runtime.stage.world.minY)/(runtime.stage.world.maxY-runtime.stage.world.minY);d.style.bottom=`calc(8px + ${clamp(pct,0,1)*100}% - 5px)`;root.appendChild(d);}}
