  function updateHud(){if(!runtime)return;const sp=document.getElementById('spVal'),wave=document.getElementById('waveVal'),lives=document.getElementById('livesVal');if(sp)sp.textContent=Math.floor(runtime.sp);if(wave)wave.textContent=`${Math.min(runtime.kills,runtime.killGoal)}/${runtime.killGoal}`;if(lives)lives.textContent=runtime.lives;const phase=document.getElementById('ttdMsPhaseV4'),flag=document.getElementById('ttdMsFlagChipV4'),summon=document.getElementById('ttdMsSummonV4');if(phase){const remain=runtime.phase==='transition'?runtime.stage.timing.travel-runtime.phaseT:runtime.stopIndex===runtime.stage.cameraStops.length-1?0:runtime.stage.timing.pause-runtime.phaseT;phase.textContent=runtime.phase==='transition'?`MOVING ${Math.max(0,Math.ceil(remain))}s`:runtime.stopIndex===runtime.stage.cameraStops.length-1?'FINAL':`PAUSE ${Math.max(0,Math.ceil(remain))}s`;}if(flag){flag.textContent=flagHudText();flag.classList.toggle('you',playerHoldsFlag());flag.classList.toggle('enemy',flagHolder()?.faction==='enemy');}if(summon){summon.innerHTML=`Summon<br><small>${runtime.summonCost} SP</small>`;summon.disabled=runtime.finished||runtime.sp<runtime.summonCost||!currentSummonZones().length;}updateRouteControls();updateProgress();}
  function flagHudText(){const h=flagHolder();if(h)return h.faction==='player'?'FLAG · YOU':'FLAG · ENEMY';if(runtime.flag?.state==='loose')return'FLAG · LOOSE';if(runtime.flag?.state==='respawning')return'FLAG · RETURN';return'FLAG · HOME';}
  function updateRouteControls(){const routes=document.getElementById('ttdMsRoutesV4'),hint=document.getElementById('ttdMsHintV4');if(!routes||!hint)return;routes.innerHTML='';const ent=runtime.entities.find(e=>e.alive&&e.id===runtime.selectedId);if(!ent){hint.textContent=runtime.kills>=runtime.killGoal&&!playerHoldsFlag()?`${runtime.killGoal} KOs reached — get a Die to ${crownLabel()} and claim the flag.`:runtime.phase==='transition'?'Camera moving — top/bottom route timing is your risk.':'Tap a Die to select it, or summon onto a safe visible surface.';return;}if(ent.moving){hint.textContent=`${ent.name} is marching and cannot attack.`;return;}const opts=playerRouteOptions(ent);hint.textContent=ent.awaitingBranch?'Choose the next physical route.':`${ent.name} · ${ent.dot} pip · tap a connected surface or another open spot.`;for(const o of opts){const n=node(o.to),btn=document.createElement('button');btn.type='button';btn.className='ttdMsRouteBtnV4';const danger=runtime.phase==='transition'&&transitionMargin(o.ed,ent.moveSpeed)<8;if(danger)btn.classList.add('danger');btn.textContent=(danger?'⚠ ':'')+(n?.name||o.to);btn.addEventListener('click',()=>{if(choosePlayerRoute(ent,o.ed.id))updateHud();});routes.appendChild(btn);}}

  function poly(g,pts,fill,stroke,width=1){g.beginPath();g.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)g.lineTo(pts[i].x,pts[i].y);g.closePath();if(fill){g.fillStyle=fill;g.fill();}if(stroke){g.strokeStyle=stroke;g.lineWidth=width;g.stroke();}}
