  function roundedQuad(g,pts,r=8){const n=pts.length,gp=[];for(let i=0;i<n;i++){const prev=pts[(i+n-1)%n],cur=pts[i],next=pts[(i+1)%n],d1=Math.hypot(prev.x-cur.x,prev.y-cur.y)||1,d2=Math.hypot(next.x-cur.x,next.y-cur.y)||1,rr=Math.min(r,d1*.18,d2*.18);gp.push({a:{x:cur.x+(prev.x-cur.x)*rr/d1,y:cur.y+(prev.y-cur.y)*rr/d1},b:{x:cur.x+(next.x-cur.x)*rr/d2,y:cur.y+(next.y-cur.y)*rr/d2},c:cur});}g.beginPath();g.moveTo(gp[0].b.x,gp[0].b.y);for(let i=1;i<=n;i++){const q=gp[i%n];g.lineTo(q.a.x,q.a.y);g.quadraticCurveTo(q.c.x,q.c.y,q.b.x,q.b.y);}g.closePath();}
  function drawConstructionBackground(g){const W=runtime.w,H=runtime.h,p=runtime.stage.palette||{},sky=g.createLinearGradient(0,0,0,H);sky.addColorStop(0,p.skyTop||'#4f9fd5');sky.addColorStop(1,p.skyBottom||'#d4efff');g.fillStyle=sky;g.fillRect(0,0,W,H);const drift=(runtime.cameraY*.035)%160;g.fillStyle='rgba(246,249,247,.80)';for(let i=0;i<7;i++){const x=((i*137+42)%Math.max(1,W+160))-80,y=48+(i%3)*64+drift*.10,r=25+(i%2)*12;g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.arc(x+r*.8,y+5,r*.72,0,Math.PI*2);g.arc(x-r*.75,y+8,r*.62,0,Math.PI*2);g.fill();}g.fillStyle='rgba(90,104,112,.16)';g.fillRect(-35,H*.68,115,H*.32);g.fillRect(W-75,H*.62,120,H*.38);}
  function drawBackground(g){if(runtime.stage.theme==='construction'){drawConstructionBackground(g);return;}const W=runtime.w,H=runtime.h,sky=g.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#03050d');sky.addColorStop(.52,'#0a1020');sky.addColorStop(1,'#111729');g.fillStyle=sky;g.fillRect(0,0,W,H);const drift=runtime.cameraY*.045;for(let layer=0;layer<3;layer++){const alpha=.28-layer*.055,speed=.04+layer*.025;for(let i=0;i<9;i++){const bw=70+(i%3)*28,bh=220+(i%4)*90,x=((i*143+layer*51-runtime.cameraX*speed)%(W+220))-110,y=H*.56+((drift*(layer+1))%180)-bh;g.fillStyle=`rgba(${12+layer*7},${16+layer*8},${31+layer*10},${alpha+.35})`;g.fillRect(x,y,bw,bh);g.fillStyle=`rgba(240,210,115,${.07+layer*.018})`;for(let yy=y+15;yy<y+bh-8;yy+=20)for(let xx=x+10;xx<x+bw-8;xx+=18)if(((xx+yy+i*13)|0)%4)g.fillRect(xx,yy,4,6);}}g.save();g.globalAlpha=.65;g.fillStyle='#d9e5f7';g.beginPath();g.arc(W*.78,H*.13,Math.max(16,W*.035),0,Math.PI*2);g.fill();g.restore();}
  function constructionZonePalette(z){const p=runtime.stage.palette||{};if(z.material==='construction_ground')return[p.constructionGround||'#858985','#a4a7a3','#6f7370','#7b7e7a'];if(z.material==='wood')return[p.woodDark||'#6e432f',p.wood||'#a66f47','#4c3025','#5a3828'];if(z.material==='yellow_platform')return['#9d732a',p.yellow||'#d0a13b','#6e4f1f','#805c22'];if(z.material==='container')return['#566b75',p.container||'#6e8793','#3e5058','#485c65'];return[p.concreteShade||'#858984',p.concrete||'#b9bbb6','#6f716e','#7c7e7a'];}
  function drawZone(g,z){const top=zoneQuad(z),fac=Math.max(25,z.facade||35),bottom=zoneQuad(z,z.y-fac),construction=runtime.stage.theme==='construction';let pal,sideA,sideB,outline;if(construction){const cp=constructionZonePalette(z);pal=[cp[0],cp[1]];sideA=cp[2];sideB=cp[3];outline='rgba(75,70,63,.72)';}else{pal=z.material==='neon'?['#222a44','#34405d']:z.material==='awning'?['#4a2635','#723d50']:z.material==='metal'||z.material==='scaffold'?['#252b37','#3a4350']:['#202532','#343a49'];sideA='#090d17';sideB='#0c111c';outline='rgba(9,12,20,.9)';}poly(g,[top[3],top[2],bottom[2],bottom[3]],sideA,'rgba(255,255,255,.045)',1);poly(g,[top[1],top[2],bottom[2],bottom[1]],sideB,'rgba(255,255,255,.045)',1);const grad=g.createLinearGradient(0,Math.min(...top.map(p=>p.y)),0,Math.max(...top.map(p=>p.y)));grad.addColorStop(0,pal[1]);grad.addColorStop(1,pal[0]);poly(g,top,grad,outline,1.5);if(!construction&&z.facade>90){g.fillStyle='rgba(239,210,113,.08)';for(let row=1;row<5;row++)for(let col=1;col<Math.max(3,Math.round(z.w/90));col++){const tx=col/Math.max(3,Math.round(z.w/90)),ty=row/5,a=bottom[3],b=bottom[2],c=top[3],d=top[2],x=lerp(lerp(a.x,b.x,tx),lerp(c.x,d.x,tx),ty),y=lerp(lerp(a.y,b.y,tx),lerp(c.y,d.y,tx),ty);g.fillRect(x-2,y-3,4,6);}}}
  function drawConnectors(g){for(const ed of runtime.stage.edges){const a=node(ed.from),b=node(ed.to);if(!a||!b)continue;const A=project(a.x,a.z,a.y+7),B=project(b.x,b.z,b.y+7),enabled=edgeEnabled(ed),construction=runtime.stage.theme==='construction';g.save();g.lineCap='round';g.strokeStyle=enabled?(construction?(ed.kind==='scaffold'?'rgba(151,112,39,.78)':'rgba(111,69,45,.74)'):'rgba(82,94,125,.88)'):'rgba(96,52,61,.35)';g.lineWidth=ed.kind==='scaffold'?8:5;g.beginPath();g.moveTo(A.x,A.y+5);g.lineTo(B.x,B.y+5);g.stroke();g.strokeStyle=enabled?(construction?'rgba(235,230,215,.34)':'rgba(177,187,211,.46)'):'rgba(160,90,95,.28)';g.lineWidth=1.5;g.setLineDash(enabled?[]:[7,7]);g.beginPath();g.moveTo(A.x,A.y);g.lineTo(B.x,B.y);g.stroke();g.setLineDash([]);if(enabled&&['stairs','fire_escape','scaffold'].includes(ed.kind)){const dx=B.x-A.x,dy=B.y-A.y,len=Math.hypot(dx,dy)||1,nx=-dy/len,ny=dx/len;for(let i=1;i<7;i++){const t=i/7,x=lerp(A.x,B.x,t),y=lerp(A.y,B.y,t);g.strokeStyle=construction?'rgba(78,52,37,.44)':'rgba(205,212,226,.34)';g.lineWidth=1;g.beginPath();g.moveTo(x-nx*6,y-ny*6);g.lineTo(x+nx*6,y+ny*6);g.stroke();}}g.restore();}}
  function drawSafe(g){g.save();g.lineWidth=1.5;for(const z of runtime.stage.zones){const q=zoneQuad(z,z.y+9);if(q.every(p=>p.y<-80||p.y>runtime.h+80))continue;roundedQuad(g,q,8);g.strokeStyle=SAFE_LINE;g.stroke();for(let i=0;i<z.spots.length;i++){const p=project(z.spots[i].x,z.spots[i].z,z.spots[i].y+5),occ=!!spotOwner(z.id,i,null);g.strokeStyle=occ?'rgba(255,255,255,.10)':SAFE_LINE;g.lineWidth=1.4;g.beginPath();g.ellipse(p.x,p.y,6*p.scale,3.4*p.scale,0,0,Math.PI*2);g.stroke();}if(z.choke){const p=project(z.x,z.z,z.y+14);g.fillStyle='rgba(243,212,145,.72)';g.font="700 8px 'Space Mono',monospace";g.textAlign='center';g.fillText('CHOKE',p.x,p.y-9);}}for(const ed of runtime.stage.edges){if(!edgeEnabled(ed))continue;const a=node(ed.from),b=node(ed.to),A=project(a.x,a.z,a.y+12),B=project(b.x,b.z,b.y+12);g.strokeStyle=runtime.stage.theme==='construction'?'rgba(255,255,255,.18)':SAFE_LINE;g.lineWidth=1.5;g.beginPath();g.moveTo(A.x,A.y);g.lineTo(B.x,B.y);g.stroke();}for(const j of runtime.stage.junctions){if(adjacent(j.id).filter(edgeEnabled).length<3)continue;const p=project(j.x,j.z,j.y+14),ang=[0,Math.PI*2/3,Math.PI*4/3];for(const a of ang){g.fillStyle='rgba(255,255,255,.42)';g.beginPath();g.arc(p.x+Math.cos(a)*7,p.y+Math.sin(a)*4,2,0,Math.PI*2);g.fill();}}g.restore();}
