  function drawDestructibles(g){for(const d of runtime.destructibles){const p=project(d.x,d.z,d.y+5),s=p.scale;if(!visiblePoint(p,100))continue;g.save();g.translate(p.x,p.y);g.scale(s,s);g.globalAlpha=d.broken?.28:1;g.fillStyle=d.flash?'#fff0d2':d.guard?'#59636f':'#6a5040';g.strokeStyle=d.guard?'#b8c6d4':'#d1a46e';g.lineWidth=2;if(d.broken){g.rotate(-.20);g.fillRect(-27,-4,54,8);}else if(d.guard){g.fillRect(-36,-21,72,5);for(let x=-30;x<=30;x+=15)g.fillRect(x,-21,3,22);}else{g.fillRect(-27,-35,54,35);for(let x=-20;x<=18;x+=13){g.beginPath();g.moveTo(x,-34);g.lineTo(x+9,0);g.stroke();}}g.restore();if(!d.broken){const pct=d.hp/d.maxHp;g.fillStyle='rgba(0,0,0,.65)';g.fillRect(p.x-26,p.y-43*s,52,5);g.fillStyle=pct>.5?'#d9b26a':'#e2584f';g.fillRect(p.x-25,p.y-42*s,50*pct,3);}}}
